int countComponents(int n, List<(int, int)> edges) {
  final adj = List.generate(n, (_) => <int>[]);
  for (final (u, v) in edges) {
    adj[u].add(v);
    adj[v].add(u);
  }
  final seen = List.filled(n, false);
  var count = 0;
  for (var s = 0; s < n; s++) {
    if (seen[s]) continue;
    count++;
    final stack = [s];
    seen[s] = true;
    while (stack.isNotEmpty) {
      for (final w in adj[stack.removeLast()]) {
        if (!seen[w]) {
          seen[w] = true;
          stack.add(w);
        }
      }
    }
  }
  return count;
}

