List<int> withinK(Map<int, List<int>> g, int start, int k) {
  var frontier = [start];
  final seen = {start};
  for (var step = 0; step < k; step++) {
    final next = <int>[];
    for (final v in frontier) {
      for (final w in g[v]!) {
        if (seen.add(w)) next.add(w);
      }
    }
    frontier = next;
  }
  return seen.toList()..sort();
}

void main() {
  final g = {1: [2], 2: [1, 3], 3: [2, 4], 4: [3]};
  print(withinK(g, 1, 2));
}
